    def _set(
        self,
        type_checker: _types.TypeChecker | None = None,
        **kwargs: Any,
    ) -> None:
        if type_checker is not None and self._type_checker is _unset:
            self._type_checker = type_checker

        for k, v in kwargs.items():
            if getattr(self, k) is _unset:
                setattr(self, k, v)

    def _contents(self):
        attrs = (
            "message", "cause", "context", "validator", "validator_value",
            "path", "schema_path", "instance", "schema", "parent",
        )
        return {attr: getattr(self, attr) for attr in attrs}

    def _matches_type(self) -> bool:
        try:
            # We ignore this as we want to simply crash if this happens
            expected = self.schema["type"]  # type: ignore[index]
        except (KeyError, TypeError):
            return False

        if isinstance(expected, str):
            return self._type_checker.is_type(self.instance, expected)

        return any(
            self._type_checker.is_type(self.instance, expected_type)
            for expected_type in expected
        )


class ValidationError(_Error):
    """
    An instance was invalid under a provided schema.
    """

    _word_for_schema_in_error_message = "schema"

    def test_hashable(self):
        {exceptions.ValidationError("")}
        {exceptions.SchemaError("")}


class TestJsonPathRendering(TestCase):
    def test_str(self):
        e = exceptions.ValidationError(
            path=["x"],
            message="1",
            validator="foo",
            instance="i1",
        )
        self.assertEqual(e.json_path, "$.x")

    def test_numeric_str(self):
        e = exceptions.ValidationError(
            path=["1"],
            message="1",
            validator="foo",
            instance="i1",
        )
        self.assertEqual(e.json_path, "$['1']")

    def test_space_str(self):
        e = exceptions.ValidationError(
            path=[" "],
            message="1",
            validator="foo",
            instance="i1",
        )
        self.assertEqual(e.json_path, "$[' ']")

    def test_backslash_single_quote(self):
        e = exceptions.ValidationError(
            path=[r"\'"],
            message="1",
            validator="foo",
            instance="i1",
        )
        self.assertEqual(e.json_path, r"$['\\\'']")

    def test_underscore(self):
        e = exceptions.ValidationError(
            path=["_"],
            message="1",
            validator="foo",
            instance="i1",
        )
        self.assertEqual(e.json_path, r"$['_']")

