def json_path(self) -> str:
    import re
    path = "$"
    for elem in self.absolute_path:
        if isinstance(elem, int):
            path += "[" + str(elem) + "]"
        else:
            if re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', elem):
                path += "." + elem
            else:
                escaped = elem.replace("\\", "\\\\").replace("'", "\\'")
                path += "['" + escaped + "']"
    return path

